"""A2A output channel: streams artifact deltas and terminal task status events."""

from __future__ import annotations

import uuid
from dataclasses import replace
from typing import Any, Literal, Optional, Text

import structlog
from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import Message, TaskState
from pydantic import BaseModel, ConfigDict

from rasa.core.a2a_server.a2a_task_event_publisher import (
    A2ATaskEventPublisher,
    A2ATaskPublishOperation,
)
from rasa.core.a2a_server.engine_adapter import A2AEngineAdapter, EngineCancelResult
from rasa.core.a2a_server.proto_convert import (
    STREAMED_ARTIFACT_ID_METADATA_KEY,
    TERMINAL_TEXT_SEPARATOR,
    data_part,
    text_part,
)
from rasa.core.a2a_server.task_state_mapper import TaskStateMappingResult
from rasa.core.channels.channel import OutputChannel
from rasa.dialogue_understanding.patterns.cancel import FLOW_PATTERN_CANCEL
from rasa.dialogue_understanding.patterns.internal_error import (
    FLOW_PATTERN_INTERNAL_ERROR_ID,
)
from rasa.dialogue_understanding.stack.frames.pattern_frame import PatternFlowStackFrame
from rasa.dialogue_understanding.stack.utils import (
    top_flow_frame,
)
from rasa.shared.constants import RASA_PATTERN_INTERNAL_ERROR_DEFAULT
from rasa.shared.core.constants import (
    ACTION_AGENT_REQUEST_USER_INPUT_NAME,
    ACTION_LISTEN_NAME,
)
from rasa.shared.core.events import FlowCompleted
from rasa.shared.core.trackers import DialogueStateTracker

structlogger = structlog.get_logger()

TURN_INCOMPLETE_ERROR_TYPE = "turn_incomplete"

CancelSource = Literal["orchestrator"]


class CancelTurnContext(BaseModel):
    """Separates *who initiated cancel* from *how the A2A channel should behave*.

    The executor sets this at signal time (``begin_orchestrator_cancel_turn``).
    ``A2AOutputChannel`` reads ``suppress_cancel_pattern_nlg`` during the turn;
    ``OrchestratorCancelTurn`` applies dialogue + publish without re-deriving policy.
    """

    model_config = ConfigDict(frozen=True)

    source: CancelSource
    suppress_cancel_pattern_nlg: bool

    @classmethod
    def for_orchestrator(
        cls, *, suppress_cancel_pattern_nlg: bool
    ) -> CancelTurnContext:
        """Build context for orchestrator ``tasks/cancel``."""
        return cls(
            source="orchestrator",
            suppress_cancel_pattern_nlg=suppress_cancel_pattern_nlg,
        )


def _resolve_internal_error_recovery_failure(
    mapping: TaskStateMappingResult,
    tracker: DialogueStateTracker,
) -> TaskStateMappingResult:
    """Map internal-error recovery turns to ``failed`` instead of success states.

    After ``pattern_internal_error`` completes in the same turn (e.g. circuit
    breaker), the stack may continue into ``pattern_completed`` and map to
    ``input_required``. Those turns still represent an error closure.
    """
    internal_error_completed_this_turn = any(
        isinstance(event, FlowCompleted)
        and event.flow_id == FLOW_PATTERN_INTERNAL_ERROR_ID
        for event in tracker.get_last_turn_events()
    )
    if not internal_error_completed_this_turn:
        return mapping

    if mapping.state in {
        TaskState.TASK_STATE_COMPLETED,
        TaskState.TASK_STATE_INPUT_REQUIRED,
    }:
        return TaskStateMappingResult(
            state=TaskState.TASK_STATE_FAILED,
            error_type=RASA_PATTERN_INTERNAL_ERROR_DEFAULT,
        )
    return mapping


def _resolve_turn_end(
    mapping: TaskStateMappingResult,
    tracker: DialogueStateTracker,
) -> TaskStateMappingResult:
    """Close an A2A task cycle when the processor finishes a turn.

    ``TaskStateMapper.map()`` may return ``working`` as an honest mid-turn tracker
    snapshot. At ``notify_message_processing_completed`` the A2A task must still
    reach a terminal or interactive-terminal state, not remain non-terminal.
    ``input_required`` and ``auth_required`` end because ``execute`` returns.
    ``TaskUpdater`` does not take ``final``.

    ``working`` at turn end without a listen pause (e.g. ``ActionLimitReached`` before
    ``action_listen``) maps to ``failed``. If ``latest_action`` is listen, map to
    ``input_required`` even when the mapper still returned ``working``.
    """
    if mapping.state != TaskState.TASK_STATE_WORKING:
        return mapping

    if tracker.latest_action_name in {
        ACTION_LISTEN_NAME,
        ACTION_AGENT_REQUEST_USER_INPUT_NAME,
    }:
        return TaskStateMappingResult(state=TaskState.TASK_STATE_INPUT_REQUIRED)

    return TaskStateMappingResult(
        state=TaskState.TASK_STATE_FAILED,
        error_type=TURN_INCOMPLETE_ERROR_TYPE,
        error_info={"latest_action": tracker.latest_action_name},
    )


class A2AOutputChannel(OutputChannel):
    """Publishes A2A task events while Rasa processes a turn.

    Phase 1 (send path):

    - ``send_text_message`` emits ``TaskState.TASK_STATE_WORKING`` with full text in
      ``status.message`` (flow NLG, fillers, non-streaming replies).
    - ``send_response_chunk*`` emits delta ``TaskArtifactUpdateEvent`` chunks
      with ``append`` / ``lastChunk`` only when the caller asked to stream.
      The finished utterance is then also a ``working`` message whose metadata
      ``streamed_artifact_id`` names that artifact. A caller that did not ask
      to stream receives the assembled text as one ``working`` message. A
      stream ended with ``interrupted=True`` publishes neither message and
      does not record the partial text for the terminal status.

    Phase 2 (completion): ``notify_message_processing_completed`` maps tracker
    state to a single terminal or interactive-terminal event.
    """

    def __init__(
        self,
        updater: TaskUpdater,
        recipient_id: Text,
        engine_adapter: A2AEngineAdapter,
        streaming: bool = True,
    ) -> None:
        """Bind the channel to the engine adapter supplied by the caller.

        ``streaming`` is the caller's choice for this turn and is stored on
        ``streaming_chosen``. Absent means the caller streams, which is how
        channels built outside a send request behave.
        """
        super().__init__()
        self._updater = updater
        self._publisher = A2ATaskEventPublisher(updater)
        self._recipient_id = recipient_id
        self._engine_adapter = engine_adapter
        self.streaming_chosen = streaming
        self._streaming_artifact_id: Optional[str] = None
        self._artifact_chunks_sent = False
        self._pending_artifact_chunk: Optional[str] = None
        self._task_cycle_closed = False
        self._published_task_state: TaskState | None = None
        self._user_visible_text_parts: list[str] = []
        self._conversation_repair_agent_utterance_parts: list[str] = []
        self._cancel_turn_context: CancelTurnContext | None = None
        self._turn_outcome: Any | None = None

    @property
    def cancel_turn_context(self) -> CancelTurnContext | None:
        """Set when an orchestrator (or future) cancel signal applies to this turn."""
        return self._cancel_turn_context

    @property
    def orchestrator_initiated_cancel(self) -> bool:
        """Whether an orchestrator cancel signal is active on this turn."""
        return (
            self._cancel_turn_context is not None
            and self._cancel_turn_context.source == "orchestrator"
        )

    async def record_turn_outcome(self, outcome: Any) -> None:
        """Keep the engine turn result for task-state mapping.

        A message that runs session start and then the user turn records twice.
        The later result is the one mapping sees, after both turns.
        """
        self._turn_outcome = outcome

    def begin_orchestrator_cancel_turn(self) -> None:
        """Record orchestrator cancel signal and derived channel NLG policy."""
        self._cancel_turn_context = CancelTurnContext.for_orchestrator(
            suppress_cancel_pattern_nlg=(
                not self._engine_adapter.pattern_replies_are_user_facing()
            )
        )

    @property
    def task_cycle_closed(self) -> bool:
        """Whether a terminal or interactive-terminal task event was published."""
        return self._task_cycle_closed

    @property
    def published_task_state(self) -> TaskState | None:
        """Last task state published when the A2A task cycle was closed."""
        return self._published_task_state

    @classmethod
    def name(cls) -> Text:
        return "a2a"

    @property
    def supports_streaming(self) -> bool:
        """Whether this channel can accept streamed chunks.

        Custom actions use this to stay on ``run_streaming``. Whether the
        caller asked for live tokens is ``streaming_chosen``: that chooses
        token artifacts or one assembled working message.
        """
        return True

    @property
    def wants_tracker_state(self) -> bool:
        """A2AOutputChannel only ever reads `_tracker`, never `tracker_state`."""
        return False

    def attach_tracker_state(self, tracker: DialogueStateTracker) -> None:
        super().attach_tracker_state(tracker)

    def note_last_streamed_bot_message_was_filler(self, was_filler: bool) -> None:
        """No-op: filler pacing is voice-only; A2A emits all MCP text as ``working``."""
        pass

    async def notify_message_processing_started(self) -> None:
        """Emit ``working`` before the first bot utterance.

        The executor publishes ``submitted`` before ``handle_message``; this hook runs
        when the processor starts the turn so clients are not left on ``submitted``
        until the first ``send_text_message`` or stream chunk.
        """
        await self._publisher.publish_non_terminal(
            A2ATaskPublishOperation.START_WORK,
            lambda: self._updater.start_work(),
        )

    def _mapping_for_tracker(self) -> TaskStateMappingResult:
        """Map the attached tracker, then apply the engine's turn-end rules.

        CALM may still close ``working`` from ``latest_action_name``. Mantle
        never returns ``working``. A turn that matches nothing else stays
        ``failed`` / ``turn_incomplete`` and is not closed from
        ``latest_action_name``.
        """
        if self._tracker is None:
            return TaskStateMappingResult(
                state=TaskState.TASK_STATE_FAILED,
                error_type=TURN_INCOMPLETE_ERROR_TYPE,
            )
        mapping = self._engine_adapter.map_task_state(
            self._tracker,
            outcome=self._turn_outcome,
            orchestrator_cancel=self.orchestrator_initiated_cancel,
        )
        if self._engine_adapter.uses_latest_action_for_turn_end():
            mapping = _resolve_internal_error_recovery_failure(mapping, self._tracker)
            mapping = _resolve_turn_end(mapping, self._tracker)
        return mapping

    async def notify_message_processing_completed(self) -> None:
        if self._cancel_turn_context is not None:
            # ``OrchestratorCancelTurn.run`` publishes ``canceled`` after
            # ``handle_message`` returns.
            return

        if self._tracker is None:
            # Without the tracker, the channel cannot distinguish completion
            # from a collect pause. Fail closed instead of reporting a false
            # success that releases the A2A context.
            mapping = self._mapping_for_tracker()
            message = await self._engine_adapter.build_status_data(
                mapping,
                None,
                updater=self._updater,
            )
            await self._publish_mapping_result(mapping, message)
            return

        mapping = self._mapping_for_tracker()
        conversation_repair_agent_utterances = (
            self._conversation_repair_agent_utterances_for_terminal()
        )
        message = await self._engine_adapter.build_status_data(
            mapping,
            self._tracker,
            updater=self._updater,
            user_visible_text=self._user_visible_text_for_terminal(),
            conversation_repair_agent_utterances=conversation_repair_agent_utterances,
        )
        await self._publish_mapping_result(mapping, message)

    async def publish_terminal_canceled(
        self,
        cancel_result: EngineCancelResult | None = None,
    ) -> None:
        """Publish terminal ``canceled`` (rich payload, then minimal fallback).

        *cancel_result* is the skill the engine just dropped. When the engine
        supplies it, that skill is the status value on the tracker payload and
        on the minimal fallback. CALM omits it and keeps the tracker mapping.
        """
        already_closed = self._task_cycle_closed
        if not already_closed:
            await self._publish_canceled_from_tracker(cancel_result)
        if not self._task_cycle_closed:
            await self._publish_canceled_minimal(cancel_result)
        elif self.orchestrator_initiated_cancel and already_closed:
            # Turn published input_required / completed before cancel was
            # signaled; still emit ``canceled`` for orchestrator cancel.
            await self._publish_canceled_minimal(cancel_result)

    async def _publish_canceled_from_tracker(
        self,
        cancel_result: EngineCancelResult | None = None,
    ) -> None:
        """Publish ``canceled`` with the engine skill, or the tracker mapping.

        A supplied result is the cancel, even when the turn had already mapped
        to ``failed``. CALM passes no result and still requires ``canceled``.
        """
        if self._tracker is None:
            return

        mapping = self._mapping_for_tracker()
        if cancel_result is not None:
            mapping = replace(
                mapping,
                state=TaskState.TASK_STATE_CANCELED,
                canceled_skill=cancel_result.canceled_skill,
                reason=None,
                error_type=None,
                error_info=None,
            )
        elif mapping.state != TaskState.TASK_STATE_CANCELED:
            return

        message = await self._engine_adapter.build_status_data(
            mapping,
            self._tracker,
            updater=self._updater,
            user_visible_text=self._user_visible_text_for_terminal(),
            conversation_repair_agent_utterances=(
                self._conversation_repair_agent_utterances_for_terminal()
            ),
        )
        await self._publish_mapping_result(mapping, message)

    async def _publish_canceled_minimal(
        self,
        cancel_result: EngineCancelResult | None = None,
    ) -> None:
        """Publish ``canceled`` when the tracker payload did not close the task.

        The engine skill still goes out. CALM has no result, so this payload
        stays a bare ``canceled``.
        """
        mapping = TaskStateMappingResult(
            state=TaskState.TASK_STATE_CANCELED,
            canceled_skill=(
                None if cancel_result is None else cancel_result.canceled_skill
            ),
        )
        message = await self._engine_adapter.build_status_data(
            mapping,
            self._tracker,
            updater=self._updater,
            user_visible_text=self._user_visible_text_for_terminal(),
            conversation_repair_agent_utterances=(
                self._conversation_repair_agent_utterances_for_terminal()
            ),
        )
        await self._publish_mapping_result(mapping, message)

    async def send_text_message(
        self,
        recipient_id: Text,
        text: Text,
        **kwargs: Any,
    ) -> None:
        """Emit non-streaming NLG as a ``working`` task status update.

        Implements :meth:`OutputChannel.send_text_message`. This channel is
        bound to one A2A context at construction; ``kwargs`` are accepted for
        API compatibility with :meth:`OutputChannel.send_response` but are not
        used for plain text (buttons, images, etc. use other send methods).
        """
        if recipient_id != self._recipient_id:
            raise ValueError(
                f"Recipient {recipient_id!r} does not match channel context "
                f"{self._recipient_id!r}"
            )
        _ = kwargs
        if self._is_duplicate_of_last_streamed_response(text):
            return
        await self._push_working_update(text)

    async def send_text_with_buttons(
        self,
        recipient_id: Text,
        text: Text,
        buttons: list[dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        """Publish button text as ``working``. Titles go in ``Part.data``.

        Payloads stay off the wire. The tracker ``BotUttered`` still holds
        them so a later ``set:`` tap can be matched. The text is a
        ``Part(text=...)`` on the same working update. ``kwargs`` matches
        :meth:`OutputChannel.send_text_with_buttons` (for example
        ``button_type``); only titles are published, so those arguments
        are ignored.
        """
        if recipient_id != self._recipient_id:
            raise ValueError(
                f"Recipient {recipient_id!r} does not match channel context "
                f"{self._recipient_id!r}"
            )
        del kwargs
        titles: list[str] = []
        for button in buttons:
            title = button.get("title")
            if isinstance(title, str) and title.strip():
                titles.append(title.strip())
        visible_text = text.strip() if text else ""
        if visible_text and self._is_duplicate_of_last_streamed_response(visible_text):
            visible_text = ""
        if self._should_suppress_user_facing_send():
            if visible_text:
                self._record_conversation_repair_agent_utterance(visible_text)
            return

        parts = []
        if visible_text:
            self._record_user_visible_text(visible_text)
            parts.append(text_part(visible_text))
        if titles:
            parts.append(data_part({"buttons": [{"title": title} for title in titles]}))
        if not parts:
            return
        message = self._updater.new_agent_message(parts)
        await self._publisher.publish_non_terminal(
            A2ATaskPublishOperation.START_WORK,
            lambda: self._updater.start_work(message=message),
        )

    async def send_response_chunk_start(
        self,
        recipient_id: Text,
        **kwargs: Any,
    ) -> None:
        await super().send_response_chunk_start(recipient_id, **kwargs)
        self._reset_streaming_artifact_state()

    async def send_response_chunk(
        self,
        recipient_id: Text,
        chunk: Text,
        **kwargs: Any,
    ) -> None:
        await super().send_response_chunk(recipient_id, chunk, **kwargs)
        if (
            self._should_suppress_user_facing_send()
            or not chunk
            or not self.streaming_chosen
        ):
            return
        if self._pending_artifact_chunk is not None:
            await self._emit_artifact_chunk(
                self._pending_artifact_chunk, last_chunk=False
            )
        self._pending_artifact_chunk = chunk

    async def send_response_chunk_end(
        self,
        recipient_id: Text,
        **kwargs: Any,
    ) -> None:
        await super().send_response_chunk_end(recipient_id, **kwargs)
        if self._should_suppress_user_facing_send():
            self._record_streamed_conversation_repair_agent_utterance()
            self._reset_streaming_artifact_state()
            return
        interrupted = bool(kwargs.get("interrupted"))
        if not self.streaming_chosen:
            text = self._accumulated_streaming_text.strip()
            self._reset_streaming_artifact_state()
            if text and not interrupted:
                await self._push_working_update(text)
            return
        if self._pending_artifact_chunk is not None:
            await self._emit_artifact_chunk(
                self._pending_artifact_chunk, last_chunk=True
            )
        artifact_id = self._streaming_artifact_id
        if not interrupted:
            self._record_streamed_user_visible_text()
            await self._publish_streamed_utterance(artifact_id)
        self._reset_streaming_artifact_state()

    def _is_pattern_utterance_context(self) -> bool:
        tracker = self._tracker
        if tracker is None:
            return False

        top_frame = top_flow_frame(
            tracker.stack, ignore_collect_information_pattern=True
        )
        return isinstance(top_frame, PatternFlowStackFrame)

    def _is_pattern_cancel_flow_utterance_context(self) -> bool:
        tracker = self._tracker
        if tracker is None:
            return False

        top_frame = top_flow_frame(
            tracker.stack, ignore_collect_information_pattern=True
        )
        return getattr(top_frame, "flow_id", None) == FLOW_PATTERN_CANCEL

    def _should_suppress_cancel_pattern_nlg(self) -> bool:
        """Suppress ``pattern_cancel_flow`` NLG per ``CancelTurnContext`` policy."""
        ctx = self._cancel_turn_context
        if ctx is None:
            return False
        return (
            ctx.suppress_cancel_pattern_nlg
            and self._is_pattern_cancel_flow_utterance_context()
        )

    def _should_suppress_user_facing_send(self) -> bool:
        """Hide pattern NLG from user-facing A2A parts when repair is disabled.

        When the adapter says pattern replies are user facing, pattern bot
        utterances are sent like any other reply. Otherwise they are exposed
        only in the structured task payload for orchestrators to filter.

        Orchestrator-initiated cancel can additionally suppress `pattern_cancel_flow`
        utterances based on the active ``CancelTurnContext`` policy.
        """
        if self._should_suppress_cancel_pattern_nlg():
            return True
        if self._engine_adapter.pattern_replies_are_user_facing():
            return False
        return self._is_pattern_utterance_context()

    def _reset_streaming_artifact_state(self) -> None:
        self._streaming_artifact_id = None
        self._artifact_chunks_sent = False
        self._pending_artifact_chunk = None

    async def _emit_artifact_chunk(self, chunk: str, *, last_chunk: bool) -> None:
        if self._streaming_artifact_id is None:
            self._streaming_artifact_id = str(uuid.uuid4())
        await self._publisher.publish_non_terminal(
            A2ATaskPublishOperation.ADD_ARTIFACT,
            lambda: self._updater.add_artifact(
                parts=[text_part(chunk)],
                artifact_id=self._streaming_artifact_id,
                append=self._artifact_chunks_sent,
                last_chunk=last_chunk,
            ),
        )
        self._artifact_chunks_sent = True

    async def _publish_streamed_utterance(self, artifact_id: str | None) -> None:
        """Publish the assembled stream as one ``working`` agent message.

        The text is already recorded for the terminal status, so this does not
        record it again. ``streamed_artifact_id`` is the only link a message
        can carry to the token artifact.
        """
        text = self._accumulated_streaming_text.strip()
        if not text or artifact_id is None:
            return
        message = self._updater.new_agent_message(
            [text_part(text)],
            metadata={STREAMED_ARTIFACT_ID_METADATA_KEY: artifact_id},
        )
        await self._publisher.publish_non_terminal(
            A2ATaskPublishOperation.START_WORK,
            lambda: self._updater.start_work(message=message),
        )

    async def _push_working_update(self, text: str) -> None:
        if not text.strip():
            return
        if self._should_suppress_user_facing_send():
            self._record_conversation_repair_agent_utterance(text)
            return
        self._record_user_visible_text(text)
        message = self._updater.new_agent_message([text_part(text)])
        await self._publisher.publish_non_terminal(
            A2ATaskPublishOperation.START_WORK,
            lambda: self._updater.start_work(message=message),
        )

    def _record_user_visible_text(self, text: str) -> None:
        normalized = text.strip()
        if not normalized:
            return
        if (
            self._user_visible_text_parts
            and self._user_visible_text_parts[-1] == normalized
        ):
            return
        self._user_visible_text_parts.append(normalized)

    def _record_conversation_repair_agent_utterance(self, text: str) -> None:
        normalized = text.strip()
        if not normalized:
            return
        if (
            self._conversation_repair_agent_utterance_parts
            and self._conversation_repair_agent_utterance_parts[-1] == normalized
        ):
            return
        self._conversation_repair_agent_utterance_parts.append(normalized)

    def _record_streamed_user_visible_text(self) -> None:
        self._record_user_visible_text(self._accumulated_streaming_text)

    def _record_streamed_conversation_repair_agent_utterance(self) -> None:
        self._record_conversation_repair_agent_utterance(
            self._accumulated_streaming_text
        )

    def _user_visible_text_for_terminal(self) -> str | None:
        parts = list(self._user_visible_text_parts)
        if not parts:
            return None
        return TERMINAL_TEXT_SEPARATOR.join(parts)

    def _conversation_repair_agent_utterances_for_terminal(self) -> list[str] | None:
        if not self._conversation_repair_agent_utterance_parts:
            return None
        return list(self._conversation_repair_agent_utterance_parts)

    async def _publish_mapping_result(
        self,
        mapping: TaskStateMappingResult,
        message: Message | None,
    ) -> None:
        state = mapping.state
        published_state = state
        if state == TaskState.TASK_STATE_COMPLETED:
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.COMPLETE,
                lambda: self._updater.complete(message=message),
            )
        elif state == TaskState.TASK_STATE_FAILED:
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.FAILED,
                lambda: self._updater.failed(message=message),
            )
        elif state == TaskState.TASK_STATE_REJECTED:
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.REJECT,
                lambda: self._updater.reject(message=message),
            )
        elif state == TaskState.TASK_STATE_CANCELED:
            # ``TaskUpdater.cancel`` takes no ``final``. The opening event on
            # this stream is a ``Task``, enqueued before the first status.
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.CANCEL,
                lambda: self._updater.cancel(message=message),
            )
        elif state == TaskState.TASK_STATE_INPUT_REQUIRED:
            # Interrupt states are not TaskUpdater terminals. The stream ends
            # because execute() returns after this event. Do not pass final.
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.REQUIRES_INPUT,
                lambda: self._updater.requires_input(message=message),
            )
        elif state == TaskState.TASK_STATE_AUTH_REQUIRED:
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.REQUIRES_AUTH,
                lambda: self._updater.requires_auth(message=message),
            )
        else:
            structlogger.warning(
                "a2a_server.a2a_output_channel.unexpected_terminal_mapping_state",
                mapped_state=state,
            )
            published_state = TaskState.TASK_STATE_FAILED
            await self._publisher.publish_terminal(
                A2ATaskPublishOperation.FAILED,
                lambda: self._updater.failed(message=message),
            )
        self._mark_task_cycle_closed(published_state)

    def _mark_task_cycle_closed(self, state: TaskState | None = None) -> None:
        if state is not None:
            self._published_task_state = state
        self._task_cycle_closed = True
